# Check girth
from collections import defaultdict

adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

n = 9
# BFS from each node to find shortest cycle
import sys

def shortest_cycle(adj, n):
    min_cycle = sys.maxsize
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[start] = 0
        queue = [start]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent[v] != u:
                    # found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle if min_cycle != sys.maxsize else None

print("Shortest cycle length:", shortest_cycle(adj, n))

# Check colorability with 5 colors (just greedy or backtracking)
def is_colorable(adj, n, k):
    colors = [-1]*n
    def dfs(v):
        if v == n:
            return True
        for c in range(k):
            ok = True
            for u in adj[v]:
                if colors[u] == c:
                    ok = False
                    break
            if ok:
                colors[v] = c
                if dfs(v+1):
                    return True
                colors[v] = -1
        return False
    return dfs(0)

print("5-colorable:", is_colorable(adj, n, 5))
print("3-colorable:", is_colorable(adj, n, 3))
